#include <algorithm>
#include <array>
#include <cmath>
#include <iostream>
#include <numeric>
#include <vector>

int main()
{
    std::cout << "Enter scores (-1 to finish): ";
    std::vector<int> scores{};
    int score{};
    while (std::cin >> score && score != -1)
    {
        scores.push_back(score);
    }
    if (scores.empty()) return 0;

    const double mean{ std::accumulate(scores.begin(), scores.end(), 0.0) / scores.size() };
    std::cout << "Count: " << scores.size() << "   Mean: " << mean << '\n';

    // TODO: sort a copy for the median, then the standard deviation, min, max and the histogram

    return 0;
}
